DO $patch$ DECLARE d text; anchor text; BEGIN d:=pg_get_functiondef('public.get_site_report(uuid,date)'::regprocedure); anchor:='AND (coalesce(t.completion_percentage,0)<100 OR EXISTS (SELECT 1 FROM public.site_report_task_progress p WHERE p.report_id=r.id AND p.task_id=t.id))'; IF position(anchor IN d)=0 THEN RAISE EXCEPTION 'Task filter anchor missing'; END IF; d:=replace(d,anchor,$new$AND (coalesce(t.completion_percentage,0)<100 OR EXISTS (SELECT 1 FROM public.site_report_task_progress p WHERE p.report_id=r.id AND p.task_id=t.id) OR EXISTS(SELECT 1 FROM public.site_report_task_progress p WHERE p.task_id=t.id AND p.report_id=(SELECT id FROM public.daily_measurements WHERE project_id=p_project_id AND trade='daily_site_report' AND report_status='submitted' AND NOT is_archived AND measurement_date<p_date ORDER BY measurement_date DESC LIMIT 1)))$new$); EXECUTE d; END $patch$;